import {readFileSync,writeFileSync,mkdirSync} from 'node:fs';
import {join,dirname,resolve} from 'node:path';
import {createCoverageMap} from 'istanbul-lib-coverage';
import {instrumentTypeScriptWithCoverage} from '../scripts/run-istanbul-bun-coverage';
import {createOwnedTestDirectory} from '../tests/helpers/owned-test-directory';
import {sourceHash} from '../scripts/quality-inventory';
const root=process.cwd(),storage=createOwnedTestDirectory('memory-remote-diagnostic-');
const paths=["src/infrastructure/database/database-write-admission.ts","src/application/services/extraction-pipeline.ts","src/infrastructure/database/event-log.ts","src/infrastructure/database/projection-recovery.ts","src/infrastructure/database/projection-replacement.ts","src/infrastructure/database/repositories/message-repository.ts","tests/infrastructure/database/database-write-admission.test.ts","tests/infrastructure/database/database-write-replay.test.ts","tests/infrastructure/database/extraction-process-admission.test.ts","src/application/services/extraction-pipeline.test.ts","src/infrastructure/database/repositories/message-repository.test.ts"];

const tests=paths.filter(path=>path.endsWith('.test.ts'));
const mode=process.argv[2]??'measure';if(!['measure','faults'].includes(mode))throw Error('Invalid mode');
const originals=new Map(paths.map(path=>[path,readFileSync(path,'utf8')]));
const typePath='src/domain/ports/operation-admission.ts',typeHash=sourceHash(readFileSync(typePath,'utf8'));
function put(path:string,content:string){mkdirSync(dirname(join(storage.dir,path)),{recursive:true});writeFileSync(join(storage.dir,path),content.replace(/from "commander"/g,'from '+JSON.stringify(Bun.resolveSync('commander',root))));}
const runs:any[]=[];

const faults=[{"path":"src/infrastructure/database/database-write-admission.ts","kind":"omit-acquisition-check","from":"if (!this.db.inTransaction) throw new Error(\"Database write reservation was not acquired\");","to":"","pattern":"begin-noop"},{"path":"src/infrastructure/database/database-write-admission.ts","kind":"omit-caller-refusal","from":"if (this.db.inTransaction) throw new Error(\"Database write scope cannot use a caller transaction\");","to":"","pattern":"refuses forged"},{"path":"src/infrastructure/database/database-write-admission.ts","kind":"omit-connection-binding","from":"!binding || binding.db !== db","to":"!binding","pattern":"refuses forged"},{"path":"src/infrastructure/database/database-write-admission.ts","kind":"omit-expiry-check","from":"if (!owner.open) throw new Error(\"Database write lease expired\");","to":"","pattern":"refuses forged"},{"path":"src/infrastructure/database/database-write-admission.ts","kind":"premature-commit","from":"const result = await operation();","to":"const pending = operation(); void pending.catch(() => {}); const result = undefined as T;","pattern":"drains detached"},{"path":"src/infrastructure/database/database-write-admission.ts","kind":"omit-rollback","from":"this.db.exec(\"ROLLBACK\");","to":"void 0;","pattern":"state for operation"},{"path":"src/infrastructure/database/database-write-admission.ts","kind":"hide-compound-failure","from":"if (failures.length > 1) throw new AggregateError(failures, failures.map(unknownErrorMessage).join(\"; \"));","to":"","pattern":"rollback-before|rollback-noop|rollback-after"},{"path":"src/infrastructure/database/database-write-admission.ts","kind":"omit-same-connection-registration","from":"ownedTransactions.add(this.db);","to":"","pattern":"same connection"},{"path":"src/infrastructure/database/repositories/message-repository.ts","kind":"omit-save-ownership-check","from":"assertNoDatabaseWriteScope(this.db);","to":"","pattern":"same connection"},{"path":"src/infrastructure/database/repositories/message-repository.ts","kind":"omit-batch-recheck","from":"// Use immediate mode to prevent SQLITE_BUSY\n            assertNoDatabaseWriteScope(this.db);","to":"// Use immediate mode to prevent SQLITE_BUSY","pattern":"message batches recheck"},{"path":"src/application/services/extraction-pipeline.ts","kind":"omit-extraction-write-scope","from":"runDatabaseWrite(this.db, async databaseLease => {","to":"((operation:(lease:undefined)=>Promise<any>)=>operation(undefined))(async databaseLease => {","pattern":"late-input|killed-before-audit"},{"path":"src/infrastructure/database/projection-recovery.ts","kind":"drop-replay-database-lease","from":"\"automatic\", lease, databaseLease)","to":"\"automatic\", lease)","pattern":"nested replay"},{"path":"src/infrastructure/database/event-log.ts","kind":"drop-fence-database-lease","from":"captureProjectionFence(db, databaseLease)","to":"captureProjectionFence(db)","pattern":"nested replay"},{"path":"src/infrastructure/database/event-log.ts","kind":"drop-promotion-database-lease","from":"mode === \"automatic\", databaseLease)","to":"mode === \"automatic\")","pattern":"nested replay"},{"path":"src/infrastructure/database/projection-replacement.ts","kind":"omit-caller-replay-check","from":"assertDatabaseWriteLease(db, lease);","to":"","pattern":"preserve foreign transactions"}];

try {
 for(const [path,content]of originals){
  for(const match of content.matchAll(/(?:from\s+|import\s*\()\s*["'](\.[^"']+)["']/g)) {
   const target=resolve(dirname(path),match[1]).replace(/\.js$/,'.ts'),local=target.slice(root.length+1).replaceAll('\\','/');
   if(!paths.includes(local))put(local,'export * from '+JSON.stringify(target.replaceAll('\\','/'))+';');
  }
  for(const match of content.matchAll(/source\("([^"]+)"\)/g)){
   const local=match[1].startsWith('src/')?match[1]:'src/'+match[1];if(!paths.includes(local))put(local,'export * from '+JSON.stringify(resolve(local).replaceAll('\\','/'))+';');
  }
 }
 put('capture.ts','import {afterAll} from "bun:test";import {writeFileSync} from "node:fs";afterAll(()=>writeFileSync("coverage.json",JSON.stringify((globalThis as any).__coverage__)));');
 put('bunfig.toml','[test]\ncoverage=false\npreload=['+JSON.stringify(join(root,'tests/test-setup.ts').replaceAll('\\','/'))+(mode==='measure'?',"./capture.ts"':'')+']\n');
 for(const fault of [null,...(mode==='faults'?faults:[])]) {
  for(const [path,content]of originals)put(path,mode==='measure'?instrumentTypeScriptWithCoverage(content,resolve(path)).code:content);
  if(fault){let content=originals.get(fault.path)!;const index=content.indexOf(fault.from);if(index<0)throw Error('Missing fault '+fault.kind);put(fault.path,content.slice(0,index)+fault.to+content.slice(index+fault.from.length));}
  const command=[process.execPath,'test','--timeout','15000',...tests,...(fault?['--test-name-pattern',fault.pattern]:[])];
  const child=Bun.spawnSync(command,{cwd:storage.dir,env:{...process.env,TEMP:storage.dir,TMP:storage.dir,TMPDIR:storage.dir},stdout:'pipe',stderr:'pipe',timeout:180000});
  const output=new TextDecoder().decode(child.stdout)+new TextDecoder().decode(child.stderr);runs.push({fault,command,exit:child.exitCode,output});
  writeFileSync('.git/q100-dbwrite-diagnostic-progress.json',JSON.stringify({runs},null,2));
  if(!fault&&child.exitCode!==0)throw Error('Control failed\n'+output);
  if(fault&&child.exitCode!==0&&!output.includes('(fail)'))throw Error('Fault did not reach assertions\n'+output);
 }
 let measurement;
 if(mode==='measure'){
  const raw=JSON.parse(readFileSync(join(storage.dir,'coverage.json'),'utf8')),map=createCoverageMap(raw);
  measurement={rawCoverage:raw,files:paths.map(path=>{const measured=map.fileCoverageFor(resolve(path)),data=measured.data;return {path,sourceHash:sourceHash(originals.get(path)!),metrics:measured.toSummary().data,uncoveredBranches:Object.entries(data.b).flatMap(([id,hits])=>hits.flatMap((count,index)=>count===0?[{id,index,location:data.branchMap[id]?.locations[index]}]:[])),uncoveredFunctions:Object.entries(data.f).filter(([,hits])=>hits===0).map(([id])=>data.fnMap[id])};})};
  console.log(JSON.stringify(measurement.files.map(file=>({path:file.path,metrics:file.metrics}))));
 }else console.log(JSON.stringify(runs.map(run=>({fault:run.fault?.kind,exit:run.exit}))));
 writeFileSync(`.git/q100-dbwrite-${mode}.json`,JSON.stringify({recordedAt:new Date().toISOString(),runtime:Bun.version,scope:'Scoped diagnostic only; child process instrumentation is not aggregated. No full quality acceptance.',sourceInputs:[...paths.map(path=>({path,sourceHash:sourceHash(originals.get(path)!)})),{path:typePath,sourceHash:typeHash}],runs,measurement,source:readFileSync('.git/q100-dbwrite-diagnostic.ts','utf8')},null,2)+'\n');
} finally { storage.cleanup(); }

